import { IngestPipeline } from "@514labs/moose-lib";

export interface ProductEvent {
  event_id: string;
  event_type: string; // 'view', 'add_to_cart', 'purchase'
  product_id: string;
  user_id: string;
  timestamp: Date;
  properties: Record<string, any>; // JSONB field, contains price for purchase events
  session_id?: string;
  device_type?: string;
  source?: string;
}

export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["event_type", "timestamp", "product_id"]
  },
  stream: true,
  ingestApi: true,
});

