import { Pool } from 'pg';

// Configure Postgres connection
const pool = new Pool({
  host: process.env.POSTGRES_HOST || 'localhost',
  port: parseInt(process.env.POSTGRES_PORT || '5432'),
  database: process.env.POSTGRES_DB || 'postgres',
  user: process.env.POSTGRES_USER || 'postgres',
  password: process.env.POSTGRES_PASSWORD || 'password',
});

// Moose ingestion endpoint
const MOOSE_INGEST_URL = process.env.MOOSE_INGEST_URL || 'http://localhost:4000';

export async function extractProductEvents() {
  try {
    console.log('Starting product events extraction from Postgres...');

    // Query to get all product events from raw.product_events
    const query = `
      SELECT
        id as event_id,
        event_type,
        product_id,
        user_id,
        timestamp,
        properties,
        session_id,
        device_type,
        source
      FROM raw.product_events
      ORDER BY timestamp ASC
    `;

    const result = await pool.query(query);
    console.log(`Found ${result.rows.length} events to process`);

    // Process events in batches
    const batchSize = 1000;
    for (let i = 0; i < result.rows.length; i += batchSize) {
      const batch = result.rows.slice(i, i + batchSize);

      // Transform and send to Moose
      const transformedBatch = batch.map(row => ({
        event_id: row.event_id,
        event_type: row.event_type,
        product_id: row.product_id,
        user_id: row.user_id,
        timestamp: row.timestamp,
        properties: row.properties || {},
        session_id: row.session_id,
        device_type: row.device_type,
        source: row.source,
      }));

      // Send to Moose ingestion API
      try {
        const response = await fetch(`${MOOSE_INGEST_URL}/ingest/ProductEvent`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(transformedBatch),
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        console.log(`Processed batch ${Math.floor(i/batchSize) + 1}/${Math.ceil(result.rows.length/batchSize)}`);
      } catch (error) {
        console.error(`Error processing batch ${i}:`, error);
      }
    }

    console.log('Product events extraction completed!');
  } catch (error) {
    console.error('Error extracting product events:', error);
  } finally {
    await pool.end();
  }
}

// Run extraction if called directly
if (require.main === module) {
  extractProductEvents();
}

