import { MaterializedView } from "@514labs/moose-lib";

export interface TopProduct {
  product_id: string;
  purchase_count: number;
  total_revenue: number;
  last_purchase_date: Date;
}

export const TopProductsMV = new MaterializedView<TopProduct>("TopProducts", {
  source: "ProductEvent",
  query: `
    SELECT
      product_id,
      count(*) as purchase_count,
      sum(toFloat64OrZero(JSONExtractString(properties, 'price'))) as total_revenue,
      max(timestamp) as last_purchase_date
    FROM currentDatabase().ProductEvent
    WHERE event_type = 'purchase'
      AND properties != '{}'
      AND JSONHas(properties, 'price')
    GROUP BY product_id
    ORDER BY total_revenue DESC, purchase_count DESC
  `,
  orderByFields: ["total_revenue", "purchase_count"],
});

