import { MaterializedView } from "@514labs/moose-lib";

export interface ConversionFunnel {
  product_id: string;
  views: number;
  add_to_carts: number;
  purchases: number;
  view_to_cart_rate: number;
  cart_to_purchase_rate: number;
  overall_conversion_rate: number;
}

export const ConversionFunnelMV = new MaterializedView<ConversionFunnel>("ConversionFunnel", {
  source: "ProductEvent",
  query: `
    SELECT
      product_id,
      countIf(event_type = 'view') as views,
      countIf(event_type = 'add_to_cart') as add_to_carts,
      countIf(event_type = 'purchase') as purchases,
      CASE
        WHEN countIf(event_type = 'view') = 0 THEN 0
        ELSE round(countIf(event_type = 'add_to_cart') / countIf(event_type = 'view') * 100, 2)
      END as view_to_cart_rate,
      CASE
        WHEN countIf(event_type = 'add_to_cart') = 0 THEN 0
        ELSE round(countIf(event_type = 'purchase') / countIf(event_type = 'add_to_cart') * 100, 2)
      END as cart_to_purchase_rate,
      CASE
        WHEN countIf(event_type = 'view') = 0 THEN 0
        ELSE round(countIf(event_type = 'purchase') / countIf(event_type = 'view') * 100, 2)
      END as overall_conversion_rate
    FROM currentDatabase().ProductEvent
    GROUP BY product_id
    HAVING views > 0
    ORDER BY overall_conversion_rate DESC, purchases DESC
  `,
  orderByFields: ["overall_conversion_rate", "purchases"],
});

