import { MaterializedView } from "@514labs/moose-lib";

export interface HourlyActivity {
  hour: string;
  date: string;
  views: number;
  add_to_carts: number;
  purchases: number;
  total_events: number;
  revenue: number;
}

export const HourlyActivityMV = new MaterializedView<HourlyActivity>("HourlyActivity", {
  source: "ProductEvent",
  query: `
    SELECT
      formatDateTime(timestamp, '%H:00') as hour,
      formatDateTime(timestamp, '%Y-%m-%d') as date,
      countIf(event_type = 'view') as views,
      countIf(event_type = 'add_to_cart') as add_to_carts,
      countIf(event_type = 'purchase') as purchases,
      count(*) as total_events,
      sum(
        CASE
          WHEN event_type = 'purchase' AND JSONHas(properties, 'price')
          THEN toFloat64OrZero(JSONExtractString(properties, 'price'))
          ELSE 0
        END
      ) as revenue
    FROM currentDatabase().ProductEvent
    GROUP BY
      formatDateTime(timestamp, '%H:00'),
      formatDateTime(timestamp, '%Y-%m-%d')
    ORDER BY date DESC, hour ASC
  `,
  orderByFields: ["date", "hour"],
});

