import { ApiDefinition, ApiRequest, ApiResponse } from "@514labs/moose-lib";

// Top Products API
export const TopProductsApi = new ApiDefinition<{}, any>({
  path: "/api/top-products",
  method: "GET",
  handler: async (request: ApiRequest<{}>) => {
    const query = `
      SELECT
        product_id,
        purchase_count,
        total_revenue,
        last_purchase_date
      FROM currentDatabase().TopProducts
      ORDER BY total_revenue DESC
      LIMIT 50
    `;

    const result = await request.olap.query(query);

    return {
      status: 200,
      body: {
        success: true,
        data: result,
        timestamp: new Date().toISOString()
      },
    };
  },
});

