  path: "/api/funnel",
  method: "GET",
  handler: async (request: ApiRequest<{}>) => {
    const query = `
      SELECT
        product_id,
        views,
        add_to_carts,
        purchases,
        view_to_cart_rate,
        cart_to_purchase_rate,
        overall_conversion_rate
      FROM currentDatabase().ConversionFunnel
      WHERE views > 10
      ORDER BY overall_conversion_rate DESC
      LIMIT 50
    `;

    const result = await request.olap.query(query);

    return {
      status: 200,
      body: {
        success: true,
        data: result,
        timestamp: new Date().toISOString()
